declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowAllScopesVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientAllowAllScopesAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowAllScopesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientAllowAllScopesAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that isAllowAllScopes returns null on a freshly created holder.
         */
        public function testAllowAllScopesNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTrustedClientAllowAllScopesAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isAllowAllScopesAssigned());
            $this->assertNull($holder->isAllowAllScopes());
        }
}
class ImplWithTrustedClientAllowAllScopesAttributeHolderUnitTest
{
  use TrustedClientAllowAllScopesAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAllowAllScopesRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAllowAllScopes();
    }}
